<?php
require_once __DIR__.'/config.php'; require_login();if(!fams_current_type_allows('AICS','view_records')){http_response_code(403);exit('Your user type does not have permission for this action. Contact the Site Administrator if this access is required.');}
$sheetUser=current_user()??[]; $isLpgmaSheetUser=(function_exists('fams_current_lpgma_user_id')&&fams_current_lpgma_user_id()>0)||in_array((string)($_SESSION['fams_identity']??''),['LPGMA','LPGMA_BRIDGED'],true)||(($sheetUser['identity_source']??'')==='LPGMA_BRIDGED')||((int)($sheetUser['office_id']??0)===1&&($sheetUser['role']??'')!=='social_worker'); $canEditSheet=user_is_admin()||($isLpgmaSheetUser&&fams_current_type_allows('AICS','edit_records')); $canExportSheet=fams_current_type_allows('AICS','export_records');
$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$type=trim((string)($_GET['type']??''));$office=(int)($_GET['office']??0);
$where=[];$params=[];$sheetOwnOffice=(int)($sheetUser['office_id']??0);$sheetIsSwadScoped=in_array(($sheetUser['role']??''),['social_worker','staff'],true)&&$sheetOwnOffice>1;
if($q!==''){ $where[]="(r.control_number LIKE ? OR r.client_first_name LIKE ? OR r.client_middle_name LIKE ? OR r.client_last_name LIKE ? OR r.beneficiary_first_name LIKE ? OR r.beneficiary_middle_name LIKE ? OR r.beneficiary_last_name LIKE ? OR r.barangay LIKE ? OR r.municipality LIKE ? OR r.province LIKE ? OR r.contact_number LIKE ? OR r.remarks LIKE ?)";$n="%$q%";for($i=0;$i<12;$i++)$params[]=$n; }
if(in_array($status,['WAITING','RELEASED','CANCELLED'],true)){$where[]='r.status=?';$params[]=$status;}
if(in_array($type,fa_types(),true)){$where[]='r.assistance_type=?';$params[]=$type;}
if($office>0){$where[]='r.office_id=?';$params[]=$office;}
$sheetOrder=$sheetIsSwadScoped ? ' ORDER BY CASE WHEN r.office_id='.((int)$sheetOwnOffice).' THEN 0 ELSE 1 END,r.date_submission DESC,r.id DESC' : ' ORDER BY r.date_submission DESC,r.id DESC';$sql='SELECT r.*,o.name office_name FROM aics_assistance_records r LEFT JOIN aics_offices o ON o.id=r.office_id'.($where?' WHERE '.implode(' AND ',$where):'').$sheetOrder;$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$cols=[['control_number','Control No.',false],['date_submission','Date Submission',true],['client_first_name','Client First',true],['client_middle_name','Middle',true],['client_last_name','Client Last',true],['barangay','Barangay',true],['municipality','Municipality / City',true],['province','Province',true],['beneficiary_first_name','Beneficiary First',true],['beneficiary_last_name','Beneficiary Last',true],['assistance_type','Assistance',true],['guarantee_amount','Amount',true],['remarks','Remarks',true],['office_name','SWAD Office',false],['status','Status',false],['release_date','Release Date',false]];
if(($_GET['export']??'')==='csv'){if(!$canExportSheet){http_response_code(403);exit('Your user type does not have permission to export records.');}log_action($pdo,'EXPORT_MASTERLIST_SHEET','Exported the AICS editable masterlist sheet to CSV.');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="AICS_Masterlist_'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,array_map(static fn($c)=>$c[1],$cols));foreach($rows as $r){$line=[];foreach($cols as $c){$v=$r[$c[0]]??'';if($c[0]==='guarantee_amount')$v=number_format((float)$v,2,'.','');$line[]=fams_csv_safe_cell($v);}fputcsv($out,$line);}fclose($out);exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editable Masterlist | SWAD FAMS</title><link rel="stylesheet" href="assets/app.css?v=<?=e(APP_VERSION)?>"><style>
body.sheet-page{background:#edf3f8;margin:0;color:#17324d;font-family:Inter,Segoe UI,Arial,sans-serif}.sheet-toolbar{position:sticky;top:0;z-index:1000;isolation:isolate;pointer-events:auto;background:#fff;border-bottom:1px solid #d7e1ea;box-shadow:0 3px 15px rgba(18,48,76,.10);padding:8px 12px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}.sheet-title{margin-right:auto}.sheet-title strong{display:block;color:#0a376c;font-size:14px}.sheet-title span{display:block;color:#7a8ea2;font-size:9px;margin-top:2px}.sheet-actions{display:flex;gap:6px;flex-wrap:wrap}.sheet-actions button{position:relative;z-index:1001;pointer-events:auto;touch-action:manipulation;border:1px solid #d4e0ea;background:#fff;color:#244e72;border-radius:8px;padding:8px 11px;font-size:10px;font-weight:800;cursor:pointer}.sheet-actions button:hover{background:#f2f7fb}.sheet-actions .primary{background:#0b4d92;color:#fff;border-color:#0b4d92}.sheet-actions .danger{color:#9b3333}.sheet-wrap{position:relative;z-index:0;padding:10px}.sheet-card{background:#fff;border:1px solid #cfdbe6;border-radius:10px;box-shadow:0 5px 22px #1232;overflow:auto;max-height:calc(100vh - 90px)}.sheet-table{border-collapse:separate;border-spacing:0;width:max-content;min-width:100%;font-size:9px;table-layout:fixed}.sheet-table th{position:sticky;top:0;z-index:4;background:#07366d;color:#fff;border-right:1px solid #1d558c;border-bottom:1px solid #1d558c;padding:6px 5px;text-align:center;white-space:nowrap;height:30px;box-sizing:border-box}.sheet-table th,.sheet-table td{box-sizing:border-box}.sheet-table th .col-resizer{position:absolute;right:-3px;top:0;width:7px;height:100%;cursor:col-resize;z-index:8}.sheet-table th .col-resizer:hover{background:#7eb7e6}.sheet-table td{position:relative;border-right:1px solid #d8e2eb;border-bottom:1px solid #d8e2eb;padding:5px;min-width:95px;vertical-align:top;white-space:pre-wrap;line-height:1.25;overflow:hidden}.sheet-table tbody tr:nth-child(even) td{background:#f8fafc}.sheet-table td.editable{background:#fffef2;cursor:text}.sheet-table td.editable:hover{background:#fffbd9}.sheet-table td.editable:focus{outline:2px solid #76a8cf;outline-offset:-2px;background:#fff}.sheet-table td.control{font-weight:900;color:#0b4d92;background:#f2f7fb!important;min-width:105px}.sheet-table td.amount{text-align:right;white-space:nowrap}.sheet-table td .row-resizer{position:absolute;left:0;bottom:-3px;width:100%;height:7px;cursor:row-resize;z-index:7}.sheet-table td .row-resizer:hover{background:#7eb7e6}.sheet-status{font-size:8px;font-weight:900;padding:4px 6px;border-radius:999px;display:inline-block}.sheet-status.waiting{background:#fff5d9;color:#8b6700}.sheet-status.released{background:#e6f7ec;color:#237241}.sheet-status.cancelled{background:#ffe9e9;color:#a23333}.save-state{font-size:9px;color:#6f8498;min-width:110px}.sheet-help{padding:7px 10px;background:#f5f9fc;border-bottom:1px solid #dce6ee;font-size:9px;color:#667d92;position:sticky;left:0}.sheet-help b{color:#0b4d92}.sheet-select{width:100%;border:0;background:transparent;font:inherit;color:inherit;outline:none}.resize-guide{position:fixed;display:none;z-index:100;background:#0b4d92;opacity:.35;pointer-events:none}.resize-guide.col{top:0;bottom:0;width:2px}.resize-guide.row{left:0;right:0;height:2px}.sheet-table tr.sheet-row-selected td{box-shadow:inset 0 0 0 1px #8db9da}.sheet-table tr.sheet-own-office td{background:#eef7ff!important}.sheet-table tr.sheet-own-office td.control{background:#d9edff!important}.sheet-table tr.sheet-other-office td{color:#526477}.sheet-unsaved{color:#a45b00;font-weight:800}@media print{body.sheet-page{background:#fff}.sheet-toolbar,.sheet-help,.no-print{display:none!important}.sheet-wrap{padding:0}.sheet-card{border:0;box-shadow:none;overflow:visible;max-height:none}.sheet-table{width:100%;min-width:0;font-size:6.2px;table-layout:fixed}.sheet-table th,.sheet-table td{font-size:6.2px;padding:2px;word-break:break-word}.sheet-table th{position:static}.sheet-table td{min-width:0}.sheet-table tr{break-inside:avoid;page-break-inside:avoid}.sheet-table .col-resizer,.sheet-table .row-resizer{display:none}@page{size:13in 8.5in landscape;margin:.25in}}
</style><link rel="stylesheet" href="../core/shared-sheet.css?v=<?=e(APP_VERSION)?>">
</head><body class="sheet-page"><header class="sheet-toolbar"><div class="sheet-title"><strong>SWAD FAMS • Editable Masterlist</strong><span><?=number_format(count($rows))?> record(s) • <?=e(date('M d, Y h:i A'))?></span></div><div class="sheet-actions"><?php if($canEditSheet): ?><button class="primary" onclick="saveEdits()">Save Changes</button><?php endif; ?><button onclick="window.print()">Print</button><?php if($canExportSheet): ?><button onclick="downloadExcel()">Download Excel</button><button onclick="downloadPDF()">Download PDF</button><?php endif; ?><button class="danger" onclick="closeSheet()">Close</button></div><span id="saveState" class="save-state"></span></header><div class="sheet-wrap"><div class="sheet-card"><div class="sheet-help"><b>Centralized masterlist:</b> records from all SWAD offices are displayed, with your office's records prioritized first. Assigned office is shown for each entry. Editing is available only where your account has explicit authorization. Drag a header edge to resize a column and a row edge to resize a row.</div><table class="sheet-table" id="sheetTable"><thead><tr><?php foreach($cols as $i=>$c): ?><th data-col="<?=$i?>"><?=e($c[1])?><span class="col-resizer" aria-hidden="true"></span></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $ri=>$r): ?><tr data-id="<?=$r['id']?>" data-row="<?=$ri?>" class="<?= $sheetIsSwadScoped && (int)($r['office_id']??0)===$sheetOwnOffice?'sheet-own-office':'sheet-other-office' ?>"><?php foreach($cols as $ci=>$c): $field=$c[0];$editable=$c[2] && $canEditSheet && (user_is_admin() || strtoupper((string)($r['status']??'WAITING'))==='WAITING');$v=(string)($r[$field]??''); ?><td class="<?= $field==='control_number'?'control ':'' ?><?= $field==='guarantee_amount'?'amount ':'' ?><?= $editable?'editable':'' ?>" <?= $editable?'contenteditable="true" data-field="'.e($field).'"':'' ?>><?= $field==='guarantee_amount' ? e(number_format((float)$v,2,'.','')) : e($v) ?><?php if($ci===0): ?><span class="row-resizer" aria-hidden="true"></span><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></div><div id="resizeGuide" class="resize-guide"></div>
<script>
const exportAuditCsrf=<?=json_encode(csrf_token())?>;
async function auditSheetExport(format){const body=new URLSearchParams({csrf_token:exportAuditCsrf,format,row_count:String(table?.tBodies?.[0]?.rows?.length||0)});const response=await fetch('export_event.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body,credentials:'same-origin'});if(!response.ok)throw new Error('Export authorization or audit request was denied.');return response.json();}
const changes=new Map();
const table=document.getElementById('sheetTable');
const storageKey='swad_fams_sheet_dimensions_v005';
function markChange(td){const tr=td.closest('tr');const id=tr.dataset.id;const field=td.dataset.field;changes.set(id,{...(changes.get(id)||{}),[field]:td.innerText.trim()});const s=document.getElementById('saveState');s.textContent=changes.size+' record(s) changed';s.classList.add('sheet-unsaved');}
table.querySelectorAll('td.editable').forEach(td=>td.addEventListener('input',()=>markChange(td)));
function loadDimensions(){try{const d=JSON.parse(localStorage.getItem(storageKey)||'{}');if(Array.isArray(d.cols))d.cols.forEach((w,i)=>setColumnWidth(i,w));if(Array.isArray(d.rows))d.rows.forEach((h,i)=>{const tr=table.tBodies[0].rows[i];if(tr&&h)tr.style.height=h+'px'});}catch(e){}}
function saveDimensions(){const cols=[...table.tHead.rows[0].cells].map(th=>Math.round(th.getBoundingClientRect().width));const rows=[...table.tBodies[0].rows].map(tr=>Math.round(tr.getBoundingClientRect().height));localStorage.setItem(storageKey,JSON.stringify({cols,rows}));}
function setColumnWidth(index,width){width=Math.max(70,Math.min(500,Number(width)||120));const th=table.tHead.rows[0].cells[index];if(!th)return;th.style.width=width+'px';th.style.minWidth=width+'px';th.style.maxWidth=width+'px';[...table.tBodies[0].rows].forEach(tr=>{const td=tr.cells[index];if(td){td.style.width=width+'px';td.style.minWidth=width+'px';td.style.maxWidth=width+'px'}})}
let resizing=null;
function startColResize(e,th){e.preventDefault();e.stopPropagation();resizing={type:'col',index:+th.dataset.col,start:e.clientX,startWidth:th.getBoundingClientRect().width};document.body.style.cursor='col-resize';document.body.style.userSelect='none';const g=document.getElementById('resizeGuide');g.className='resize-guide col';g.style.display='block';}
function startRowResize(e,tr){e.preventDefault();e.stopPropagation();resizing={type:'row',index:tr.rowIndex-1,start:e.clientY,startHeight:tr.getBoundingClientRect().height};document.body.style.cursor='row-resize';document.body.style.userSelect='none';const g=document.getElementById('resizeGuide');g.className='resize-guide row';g.style.display='block';}
table.querySelectorAll('.col-resizer').forEach(r=>r.addEventListener('pointerdown',e=>startColResize(e,r.parentElement)));
table.querySelectorAll('.row-resizer').forEach(r=>r.addEventListener('pointerdown',e=>startRowResize(e,r.closest('tr'))));
document.addEventListener('pointermove',e=>{if(!resizing)return;const g=document.getElementById('resizeGuide');if(resizing.type==='col'){const w=resizing.startWidth+(e.clientX-resizing.start);setColumnWidth(resizing.index,w);g.style.left=e.clientX+'px'}else{const h=Math.max(24,Math.min(240,resizing.startHeight+(e.clientY-resizing.start)));const tr=table.tBodies[0].rows[resizing.index];if(tr)tr.style.height=h+'px';g.style.top=e.clientY+'px'}});
document.addEventListener('pointerup',()=>{if(!resizing)return;saveDimensions();resizing=null;document.body.style.cursor='';document.body.style.userSelect='';const g=document.getElementById('resizeGuide');g.style.display='none';});
loadDimensions();
async function saveEdits(){if(!changes.size){document.getElementById('saveState').textContent='No changes to save.';return}const state=document.getElementById('saveState');state.textContent='Saving...';try{const r=await fetch('sheet_save.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=e(csrf_token())?>'},body:JSON.stringify({changes:Object.fromEntries(changes)})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Unable to save changes.');changes.clear();state.classList.remove('sheet-unsaved');state.textContent=d.message;setTimeout(()=>state.textContent='',3000)}catch(e){state.textContent=e.message;state.classList.add('sheet-unsaved')}}
function closeSheet(){if(changes.size&&!confirm('You have unsaved changes. Close without saving?'))return;try{window.close();}catch(e){}if(!window.closed){document.body.innerHTML='<main style="font:14px Segoe UI,Arial,sans-serif;max-width:620px;margin:12vh auto;padding:28px;background:#fff;border:1px solid #d7e1ea;border-radius:14px;color:#17324d;text-align:center"><h2 style="margin-top:0;color:#0b4d92">Editable sheet closed</h2><p>This browser does not allow a page to close its own tab unless it was opened by a script.</p><p>Please close this tab using the tab’s × button or Ctrl+W.</p></main>';}}
async function downloadExcel(){try{await auditSheetExport('xls');}catch(e){alert(e.message);return;}const clone=table.cloneNode(true);clone.querySelectorAll('tbody td').forEach(td=>{if(td.cellIndex===11)return;const value=td.textContent||'';if(/^[\x00-\x20]*[=+\-@]/.test(value))td.textContent="'"+value;});clone.querySelectorAll('[contenteditable]').forEach(td=>td.removeAttribute('contenteditable'));clone.querySelectorAll('.col-resizer,.row-resizer').forEach(x=>x.remove());const rows=[...table.tBodies[0].rows].map(tr=>Math.round(tr.getBoundingClientRect().height));[...clone.tBodies[0].rows].forEach((tr,i)=>{if(rows[i])tr.style.height=rows[i]+'px'});const cols=[...table.tHead.rows[0].cells].map(th=>Math.round(th.getBoundingClientRect().width));[...clone.tHead.rows[0].cells].forEach((th,i)=>{th.style.width=cols[i]+'px';th.style.minWidth=cols[i]+'px'});const html='\ufeff<html><head><meta charset="utf-8"><style>table{border-collapse:collapse}th,td{border:1px solid #bbb;padding:4px;font-family:Arial;font-size:10px}th{background:#07366d;color:#fff}</style></head><body>'+clone.outerHTML+'</body></html>';const blob=new Blob([html],{type:'application/vnd.ms-excel'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='SWAD_Region_II_Masterlist_'+new Date().toISOString().slice(0,10)+'.xls';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function downloadPDF(){try{await auditSheetExport('pdf');window.print();}catch(e){alert(e.message)}}
window.addEventListener('beforeunload',e=>{if(changes.size){e.preventDefault();e.returnValue=''}});
</script></body></html>
